def self_curve(u, p, kind):
    (a, b, c, d) = p
    if kind == 'rat3':
        return a * u / (1 + b * u * u) + c * u + d * u ** 3
    if kind == 'tanh3':
        return a * np.tanh(b * u) + c * u + d * u ** 3
    if kind == 'soft3':
        return a * u / np.sqrt(1 + b * u * u) + c * u + d * u ** 3
    if kind == 'inner3':
        return a * np.tanh(b * u + c * u ** 3) + d * u
    if kind == 'exp3':
        return a * u * np.exp(-b * u * u) + c * u + d * u ** 3
    if kind == 'rat4':
        return (a * u + c * u ** 3) / (1 + b * u * u + d * u ** 4)

def cross_curve(v, p, kind):
    (l, q, r, t) = p
    if kind == 'even':
        return l * v + q * v * v / (1 + r * v * v)
    if kind == 'both':
        return (l * v + q * v * v) / (1 + r * v * v)
    if kind == 'odd':
        return l * v / (1 + r * v * v) + q * v * v
    if kind == 'split':
        return l * v / (1 + r * v * v) + q * v * v / (1 + t * v * v)

def phi(u, f):
    from scipy.special import erf
    if f == 'tanh':
        return np.tanh(u)
    if f == 'atan':
        return np.arctan(u)
    if f == 'sqrt':
        return u / np.sqrt(1 + u * u)
    if f == 'rational':
        return u / (1 + u * u)
    if f == 'erf':
        from scipy.special import erf
        return erf(u)

def _self_basis(u, b, kind):
    from scipy.special import erf
    q = u * u
    if kind == 'exp':
        return u * np.exp(-b[0] * q)
    if kind == 'tanh':
        return np.tanh(b[0] * u)
    if kind == 'erf':
        return erf(b[0] * u)
    if kind == 'rational':
        return u / (1 + b[0] * q)
    if kind == 'power':
        return u / (1 + b[0] * q) ** b[1]
    if kind == 'quartic':
        return u / (1 + b[0] * q + b[1] * q * q)
    if kind == 'logistic':
        return u / (1 + np.exp(np.clip(b[0] * (q - b[1]), -50, 50)))

